var names=new System.Collections.Generic.List<object>(); foreach(var go in UnityEngine.Object.FindObjectsByType<UnityEngine.GameObject>(UnityEngine.FindObjectsSortMode.None)){if(!go.scene.IsValid())continue; if(go.name.Contains("Player")||go.name.Contains("Door")||go.name.Contains("Safety")||go.name.Contains("Survivor"))names.Add(new{name=go.name,pos=go.transform.position.ToString(),active=go.activeSelf});} return names;
